(() => {
  'use strict';

  // Keep every captured chunk in memory until the final save commits. Persist a
  // contiguous prefix so a failed write can retry without leaving gaps on disk.
  class RecordingSession {
    constructor({repository,target,take,onPersistenceError=()=>{}}){
      this.repository=repository;
      this.target=structuredClone(target);
      this.take=structuredClone(take);
      this.onPersistenceError=onPersistenceError;
      this.chunks=[];
      this.chunkDurations=[];
      this.durableCount=0;
      this.chain=Promise.resolve();
    }

    append(chunk,durationMs){
      if(!chunk?.size)return this.chain;
      this.chunks.push(chunk);
      this.chunkDurations.push(durationMs);
      this.take.durationMs=durationMs;
      this.take.mimeType ||= chunk.type||'audio/webm';
      this.chain=this.chain.catch(()=>{}).then(()=>this.flush());
      this.chain.catch(this.onPersistenceError);
      return this.chain;
    }

    async flush(){
      while(this.durableCount<this.chunks.length){
        const index=this.durableCount;
        await this.repository.saveRecordingChunk({
          id:this.take.id,target:this.target,take:{...this.take,durationMs:this.chunkDurations[index]},
          chunkCount:index+1,updatedAt:new Date().toISOString()
        },index,this.chunks[index]);
        this.durableCount++;
      }
    }

    async finish(durationMs){
      this.take.durationMs=durationMs;
      await this.chain.catch(()=>{});
      return{target:this.target,take:this.take,blob:new Blob(this.chunks,{type:this.take.mimeType||'audio/webm'})};
    }
  }

  window.CoWriterRecordingRecovery={create:options=>new RecordingSession(options),RecordingSession};
})();
