(() => {
  'use strict';

  const CLIENT_VERSION='0.6.7';
  const MINIMUM_EDIT_VERSION='0.6.7';
  const PROTOCOL_VERSION=3;
  const versionCode=value=>{const [major=0,minor=0,patch=0]=String(value||'').match(/^\d+\.\d+\.\d+/)?.[0]?.split('.').map(Number)||[];return major*1_000_000+minor*1_000+patch;};
  const compatiblePeer=payload=>Number(payload?.protocol||0)===PROTOCOL_VERSION&&versionCode(payload?.clientVersion)>=versionCode(MINIMUM_EDIT_VERSION);

  class RealtimeCollaboration {
    constructor({cloudService,songDocuments,clientId,onRemote=()=>{},onPresence=()=>{},onIncompatible=()=>{},onStatus=()=>{}}){
      this.cloudService=cloudService;this.songDocuments=songDocuments;this.clientId=clientId;this.onRemote=onRemote;this.onPresence=onPresence;this.onIncompatible=onIncompatible;this.onStatus=onStatus;this.channel=null;this.songId=null;this.context={};this.unsubscribeDocument=null;this.status='closed';this.pendingBroadcasts=new Map();this.reconnectPromise=null;this.connectionGeneration=0;this.receivedUpdates=0;this.sentUpdates=0;this.acknowledgedUpdates=0;this.suppressedAcknowledgements=0;this.lastError=null;
    }
    available(){return navigator.onLine&&this.cloudService.isConfigured()&&Boolean(this.cloudService.user());}
    setStatus(status,{clearPresence=false}={}){this.status=status;if(clearPresence)this.onPresence([]);this.onStatus(this.status);}
    async open(song,context={},options={}){
      const force=Boolean(options.force),generation=options.generation??++this.connectionGeneration;
      if(!song||song.cloudMembership?.role==='revoked'||!this.available()){await this.close();return;}
      this.context={...this.context,...context};
      if(this.reconnectPromise&&!force){await this.reconnectPromise;if(generation!==this.connectionGeneration)return;return this.open(song,context,{generation});}
      if(this.songId===song.id&&this.channel&&!force&&['connecting','live'].includes(this.status)){await this.setContext(context);return;}
      await this.close({announce:false,preservePending:force,preserveGeneration:true});if(generation!==this.connectionGeneration)return;this.songId=song.id;this.context=context;this.setStatus('connecting',{clearPresence:true});
      const user=this.cloudService.user(),channel=this.cloudService.realtimeChannel(`song:${song.id}`,user.id);this.channel=channel;
      channel.on('broadcast',{event:'yjs-update'},async({payload})=>{
        if(channel!==this.channel||!payload||payload.sender===this.clientId||payload.songId!==this.songId)return;
        if(!compatiblePeer(payload)){this.onIncompatible(payload.clientVersion||'an incompatible version');return;}
        const localSong=this.context.song?.();if(!localSong)return;
        try{const next=await this.songDocuments.apply(this.songId,payload.updateBase64,localSong);this.receivedUpdates+=1;this.lastError=null;this.onRemote(next,payload);if(this.shouldAcknowledge(payload.sender)){this.channel?.send({type:'broadcast',event:'yjs-ack',payload:{songId:this.songId,target:payload.sender,updateId:payload.updateId,sender:this.clientId}}).catch(()=>{});}else this.suppressedAcknowledgements+=1;}
        catch(error){this.lastError=error?.message||String(error);console.warn('Live update could not be applied',error);}
      });
      channel.on('broadcast',{event:'yjs-ack'},({payload})=>{if(channel!==this.channel||payload?.target!==this.clientId||payload.songId!==this.songId)return;const pending=this.pendingBroadcasts.get(payload.updateId);if(pending)clearTimeout(pending.timer);if(pending)this.acknowledgedUpdates+=1;this.pendingBroadcasts.delete(payload.updateId);});
      channel.on('broadcast',{event:'asset-metadata'},({payload})=>{if(channel===this.channel&&payload?.songId===this.songId)this.onRemote(null,payload);});
      channel.on('presence',{event:'sync'},()=>{if(channel===this.channel)this.publishPresence();});
      channel.on('presence',{event:'join'},()=>{if(channel===this.channel)this.publishPresence();});
      channel.on('presence',{event:'leave'},()=>{if(channel===this.channel)this.publishPresence();});
      this.unsubscribeDocument=this.songDocuments.subscribe(song.id,updateBase64=>{
        if(!this.channel||!this.available())return;
        const payload={songId:this.songId,updateId:crypto.randomUUID(),updateBase64,sender:this.clientId,protocol:PROTOCOL_VERSION,clientVersion:CLIENT_VERSION};this.queueUpdate(payload);
      });
      channel.subscribe(async status=>{
        if(channel!==this.channel)return;
        if(status==='SUBSCRIBED'){
          this.setStatus('live');
          try{await channel.track(this.presencePayload());}catch(error){this.lastError=error?.message||String(error);this.setStatus('retrying',{clearPresence:true});return;}
          for(const record of this.pendingBroadcasts.values()){clearTimeout(record.timer);record.timer=null;record.attempts=0;this.transmitUpdate(record);}
        }
        else if(['CHANNEL_ERROR','TIMED_OUT'].includes(status))this.setStatus('retrying',{clearPresence:true});
        else if(status==='CLOSED')this.setStatus('closed',{clearPresence:true});
      });
    }
    async reconnect(song,context={}){
      if(!song||song.cloudMembership?.role==='revoked'||!this.available()){await this.close();return;}
      this.context={...this.context,...context};
      if(this.reconnectPromise)return this.reconnectPromise;
      const generation=++this.connectionGeneration;
      this.reconnectPromise=(async()=>{
        this.setStatus('retrying',{clearPresence:true});
        await this.close({announce:false,preservePending:true,preserveGeneration:true});
        if(generation!==this.connectionGeneration)return;
        await this.open(song,this.context,{force:true,generation});
      })().finally(()=>{this.reconnectPromise=null;});
      return this.reconnectPromise;
    }
    pause(){if(!this.channel)return;this.setStatus('retrying',{clearPresence:true});try{return Promise.resolve(this.channel.untrack?.()).catch(error=>{this.lastError=error?.message||String(error);});}catch(error){this.lastError=error?.message||String(error);}}
    queueUpdate(payload){const record={payload,attempts:0,timer:null};this.pendingBroadcasts.set(payload.updateId,record);this.transmitUpdate(record);}
    hasRemotePeers(){const ownUser=this.cloudService.user()?.id;return Object.values(this.channel?.presenceState()||{}).flat().some(person=>person.clientId!==this.clientId&&person.userId!==ownUser);}
    shouldAcknowledge(sender){const candidates=Object.values(this.channel?.presenceState()||{}).flat().map(person=>String(person.clientId||'')).filter(clientId=>clientId&&clientId!==sender).sort();return candidates[0]===this.clientId;}
    transmitUpdate(record){if(!this.pendingBroadcasts.has(record.payload.updateId)||!this.channel||!this.available())return;clearTimeout(record.timer);record.timer=null;record.attempts+=1;const expectAck=this.hasRemotePeers();if(expectAck)record.timer=setTimeout(()=>{if(record.attempts<4)this.transmitUpdate(record);else{this.pendingBroadcasts.delete(record.payload.updateId);this.lastError='Live update acknowledgement timed out';this.setStatus('retrying',{clearPresence:true});}},350*record.attempts);this.channel.send({type:'broadcast',event:'yjs-update',payload:record.payload}).then(result=>{if(result==='ok'){this.sentUpdates+=1;if(!expectAck)this.pendingBroadcasts.delete(record.payload.updateId);return;}this.lastError=`Realtime broadcast ${result||'failed'}`;if(!expectAck)this.pendingBroadcasts.delete(record.payload.updateId);}).catch(error=>{this.lastError=error?.message||String(error);if(!expectAck)this.pendingBroadcasts.delete(record.payload.updateId);});}
    presencePayload(){const user=this.cloudService.user(),context=this.context;return{userId:user?.id,email:user?.email||'',clientId:this.clientId,clientVersion:CLIENT_VERSION,protocol:PROTOCOL_VERSION,activeView:context.view?.()||'write',activeSectionId:context.section?.()||null,activeLineId:context.line?.()||null,shapeSelection:context.shapeSelection?.()||[],onlineAt:new Date().toISOString()};}
    async setContext(context={}){this.context={...this.context,...context};if(this.channel&&this.status==='live')try{await this.channel.track(this.presencePayload());}catch(error){this.lastError=error?.message||String(error);this.setStatus('retrying',{clearPresence:true});}}
    publishPresence(){if(!this.channel)return;const ownUser=this.cloudService.user()?.id,people=Object.values(this.channel.presenceState()||{}).flat().filter(person=>person.clientId!==this.clientId&&person.userId!==ownUser);for(const person of people)if(!compatiblePeer(person))this.onIncompatible(person.clientVersion||'an incompatible version');this.onPresence(people.filter(compatiblePeer));}
    async broadcastAsset(metadata){if(!this.channel||this.status!=='live'||metadata?.songId!==this.songId)return;await this.channel.send({type:'broadcast',event:'asset-metadata',payload:{songId:this.songId,sender:this.clientId,metadata}});}
    debug(){return{songId:this.songId,status:this.status,receivedUpdates:this.receivedUpdates,sentUpdates:this.sentUpdates,acknowledgedUpdates:this.acknowledgedUpdates,suppressedAcknowledgements:this.suppressedAcknowledgements,pendingBroadcasts:this.pendingBroadcasts.size,reconnecting:Boolean(this.reconnectPromise),connectionGeneration:this.connectionGeneration,lastError:this.lastError};}
    async close({announce=true,preservePending=false,preserveGeneration=false}={}){
      if(!preserveGeneration)this.connectionGeneration+=1;
      this.unsubscribeDocument?.();this.unsubscribeDocument=null;
      for(const pending of this.pendingBroadcasts.values()){clearTimeout(pending.timer);pending.timer=null;}
      if(!preservePending)this.pendingBroadcasts.clear();
      const channel=this.channel;this.channel=null;this.songId=null;this.status='closed';this.onPresence([]);if(announce)this.onStatus(this.status);if(channel)await this.cloudService.removeRealtimeChannel(channel);
    }
  }

  window.CoWriterRealtime={create:options=>new RealtimeCollaboration(options),RealtimeCollaboration,CLIENT_VERSION,MINIMUM_EDIT_VERSION,PROTOCOL_VERSION};
})();
