      const next=structuredClone(this.manifest);if(writing){next.writingSnapshots ||= {};const json=JSON.stringify(writing),bytes=new TextEncoder().encode(json),hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))).map(v=>v.toString(16).padStart(2,'0')).join('');next.writingSnapshots[hash]=writing;segment.writingSnapshotId=hash;}next.segments.push(segment);next.capturedMs=endMs;next.reminderMs+=durationMs;
      const cutoff=endMs-this.windowMs,expired=next.segments.filter(item=>item.endMs<=cutoff);next.segments=next.segments.filter(item=>item.endMs>cutoff);
