      await this.chain;if(!this.manifest.segments.length)throw new Error('No complete audio has been retained yet');
      if(typeof this.createWriter!=='function')throw new Error('Compressed audio export is unavailable');
      const cutoff=Math.max(0,this.manifest.capturedMs-this.windowMs),writer=await this.createWriter();
