function configured(){
  if(globalThis.document?.documentElement?.dataset?.localOnly==='true')return false;
  const hosted=/^https:\/\/[^/]+\.supabase\.co\/?$/i.test(SUPABASE_URL),local=ALLOW_LOCAL_SUPABASE&&/^http:\/\/(127\.0\.0\.1|localhost)(:\d+)?\/?$/i.test(SUPABASE_URL);
  return (hosted||local)&&SUPABASE_PUBLISHABLE_KEY.length>20;
}

function requireSuccess(result,label){
  if(result?.error)throw new Error(`${label}: ${result.error.message}`);
  return result?.data;
}

function assetBlob(record){
  if(record instanceof Blob)return record;
  if(record?.blob instanceof Blob)return record.blob;
  if(record?.bytes instanceof ArrayBuffer)return new Blob([record.bytes],{type:record.mimeType||'application/octet-stream'});
  if(ArrayBuffer.isView(record?.bytes))return new Blob([record.bytes],{type:record.mimeType||'application/octet-stream'});
  return null;
}

function songForAsset(creative,id,kind){
  return (creative.songs||[]).find(song=>kind==='audio'?(song.takes||[]).some(take=>take.id===id):(song.attachmentIds||[]).includes(id))?.id||null;
}

