// Shared, offline AAC/MP4 writer for kept Retainer audio and trimmed playback.
// MediaRecorder originals stay untouched; only the selected export is encoded.
import {MP4,WEBM,WAVE,AudioBufferSink,AudioBufferSource,BlobSource,BufferTarget,Input,Mp4OutputFormat,Output,Quality,canEncodeAudio} from 'mediabunny';

// The guided-review release uses only a browser's native AAC encoder. The
// optional FFmpeg/WASM encoder remains available for local development until
// its exact corresponding source can be supplied with a distributed build.
const bundledFallbackAllowed=import.meta.env.DEV||import.meta.env.VITE_COWRITER_AAC_FALLBACK==='enabled';

let encoderReady;
async function ensureEncoder(){
  encoderReady ||= (async()=>{
    if(!(await canEncodeAudio('aac'))&&bundledFallbackAllowed){
      const {registerAacEncoder}=await import('@mediabunny/aac-encoder');
      registerAacEncoder();
    }
    if(!(await canEncodeAudio('aac')))throw new Error('AAC export is unavailable in this browser. Your original audio remains on this device; try an updated browser before trimming or keeping it.');
  })();
  try{await encoderReady;}catch(error){encoderReady=null;throw error;}
}

function frameBounds(buffer,start=0,end=buffer?.duration){
  if(!buffer?.getChannelData||!Number.isFinite(buffer.sampleRate)||!Number.isFinite(buffer.length)||buffer.length<1)throw new Error('Decoded audio is required');
  const duration=buffer.length/buffer.sampleRate;
  const from=Math.max(0,Math.min(buffer.length,Math.floor(Math.max(0,Number(start)||0)*buffer.sampleRate)));
  const to=Math.max(from,Math.min(buffer.length,Math.ceil(Math.min(duration,Number.isFinite(end)?end:duration)*buffer.sampleRate)));
  if(to<=from)throw new Error('The selected audio passage is empty');
  return {from,to};
}

function sliceBuffer(buffer,from,to){
  const channels=Math.max(1,Math.min(2,buffer.numberOfChannels));
  const part=new AudioBuffer({length:to-from,numberOfChannels:channels,sampleRate:buffer.sampleRate});
  for(let channel=0;channel<channels;channel++)part.copyToChannel(buffer.getChannelData(channel).subarray(from,to),channel);
  return part;
}

async function createAacWriter({channels=1}={}){
  await ensureEncoder();
  const output=new Output({format:new Mp4OutputFormat({fastStart:'in-memory'}),target:new BufferTarget()});
  const source=new AudioBufferSource({codec:'aac',quality:new Quality({bitrate:128000}),transform:{sampleRate:48000,numberOfChannels:Math.max(1,Math.min(2,channels))}});
  output.addAudioTrack(source);
  await output.start();
  let frames=0,closed=false;
  return {
    async add(buffer,start=0,end=buffer?.duration){
      if(closed)throw new Error('Audio export is already finished');
      const bounds=frameBounds(buffer,start,end),chunkFrames=Math.max(1,Math.floor(buffer.sampleRate*10));
      for(let from=bounds.from;from<bounds.to;from+=chunkFrames){const to=Math.min(bounds.to,from+chunkFrames);await source.add(sliceBuffer(buffer,from,to));frames+=to-from;}
    },
    async finish(){
      if(closed)throw new Error('Audio export is already finished');
      if(!frames)throw new Error('There is no audio to export');
      closed=true;await output.finalize();
      const bytes=output.target.buffer;
      if(!bytes?.byteLength)throw new Error('AAC audio export produced an empty file');
      return new Blob([bytes],{type:'audio/mp4'});
    },
    async cancel(){if(!closed){closed=true;await output.cancel();}}
  };
}

async function encodeTrimmedAudio(buffer,start,end){
  const writer=await createAacWriter({channels:buffer?.numberOfChannels});
  try{await writer.add(buffer,start,end);return await writer.finish();}
  catch(error){await writer.cancel().catch(()=>{});throw error;}
}

async function decodeAudioBlob(blob){
  const Context=window.AudioContext||window.webkitAudioContext;
  if(!Context)throw new Error('Audio decoding is unavailable');
  const context=new Context();
  try{return await context.decodeAudioData(await blob.arrayBuffer());}
  catch(nativeError){
    // Some WebKit builds can record an AAC/MP4 segment that Web Audio refuses
    // to decode. WebCodecs can still read its track through Mediabunny.
    const input=new Input({source:new BlobSource(blob),formats:[MP4,WEBM,WAVE]});
    try{
      const track=await input.getPrimaryAudioTrack();
      if(!track||!(await track.canDecode()))throw nativeError;
      const parts=[];let frames=0,channels=0,sampleRate=0;
      for await(const {buffer} of new AudioBufferSink(track).buffers()){
        if(!sampleRate){sampleRate=buffer.sampleRate;channels=buffer.numberOfChannels;}
        if(buffer.sampleRate!==sampleRate||buffer.numberOfChannels!==channels)throw new Error('Audio format changed during decoding');
        parts.push(buffer);frames+=buffer.length;
      }
      if(!frames)throw nativeError;
      const joined=new AudioBuffer({length:frames,numberOfChannels:channels,sampleRate});
      for(let channel=0;channel<channels;channel++){
        const output=joined.getChannelData(channel);let offset=0;
        for(const part of parts){output.set(part.getChannelData(channel),offset);offset+=part.length;}
      }
      return joined;
    }catch{throw nativeError;}
    finally{input.dispose();}
  }finally{await context.close?.();}
}

window.CoWriterAudioExport={createAacWriter,encodeTrimmedAudio,decodeAudioBlob};
export {createAacWriter,encodeTrimmedAudio,decodeAudioBlob};
