        const tx=this.db.transaction(this.stateStore,'readwrite'),store=tx.objectStore(this.stateStore);
        store.put(record,`${this.recordingChunkPrefix(draft.id)}${String(index).padStart(10,'0')}`);
        store.put(snapshot,`recording-draft:${draft.id}`);
