    async writeRemoteState(runtime){const snapshot=clone(runtime),pending=this.writeChain.then(()=>this.persistState(snapshot,false));this.writeChain=pending.catch(()=>{});const sync=await pending;runtime.syncMeta=sync;return sync;}
