(() => {
  'use strict';
  const LEGACY_KEY = 'cowriter-pro-morning-lines-0.4.0.3';
  const exercises = [
    {name:'Keep the hand moving', prompt:'Write without stopping or correcting. Follow the next true sentence, even when it changes direction.'},
    {name:'Object in the room', prompt:'Choose one ordinary object nearby. Describe it until it begins to carry a memory, a person or a place.'},
    {name:'I remember', prompt:'Begin every new thought with “I remember.” Specific details matter more than a complete story.'},
    {name:'First line, no song', prompt:'Write ten possible opening lines. Do not turn them into a song yet; let each one open a different door.'},
    {name:'Change one sense', prompt:'Write a scene through sound, touch, smell and taste. Leave sight until the final paragraph.'},
    {name:'What is unsaid', prompt:'Write a conversation in which neither person names the thing they are actually discussing.'}
  ];
  const $ = id => document.getElementById(id);
  let host, recoveryKey, timer, deadline=null, saveTimer, generation=0, returnFocus, busy=false;
  const pendingIdeaIds=new Set();
  const now=()=>new Date().toISOString();
  const current=()=>host.getState().exercisePages.find(page=>page.id===host.getState().activeExercisePageId);
  const status=text=>$('morningLinesSaved').textContent=text;
  function normalisePages(value){return (Array.isArray(value)?value:[]).filter(page=>page&&typeof page.id==='string').map(page=>({...page,text:String(page.text||''),exercise:Number.isInteger(Number(page.exercise))&&Number(page.exercise)>=0&&Number(page.exercise)<exercises.length?Number(page.exercise):0,minutes:[0,5,10,15,25].includes(page.minutes)?page.minutes:5,createdAt:page.createdAt||now(),updatedAt:page.updatedAt||page.createdAt||now(),remainingMs:Number.isFinite(page.remainingMs)&&page.remainingMs>=0?page.remainingMs:([0,5,10,15,25].includes(page.minutes)?page.minutes:5)*60000,copies:Array.isArray(page.copies)?page.copies.filter(copy=>copy&&typeof copy.id==='string'&&typeof copy.text==='string'):[]}));}
  function journal(){
    const page=current();if(!page)return;
    try{localStorage.setItem(recoveryKey,JSON.stringify({page,ideas:host.getState().ideas.filter(idea=>pendingIdeaIds.has(idea.id))}));}
    catch(error){status('Recovery copy unavailable · keep this page open');}
  }
  async function flush(){
    clearTimeout(saveTimer);const revision=generation;
    try{await host.persist();if(revision===generation){try{localStorage.removeItem(recoveryKey);}catch(_){}pendingIdeaIds.clear();status('Saved here');}return true;}
    catch(error){status('Couldn’t save · keep this page open and retry');return false;}
  }
  function changed(){generation++;current().updatedAt=now();status('Saving…');journal();clearTimeout(saveTimer);saveTimer=setTimeout(flush,180);}
  async function action(fn){if(busy)return;busy=true;try{await fn();}finally{busy=false;}}
  function wordCount(){const count=$('morningLinesEditor').value.trim().match(/\S+/g)?.length||0;$('morningLinesWords').textContent=`${count} word${count===1?'':'s'}`;selectionChanged();}
  function selectionChanged(){const editor=$('morningLinesEditor');$('morningLinesSaveIdea').textContent=editor.selectionEnd>editor.selectionStart?'Save selection to Ideas':'Save page to Ideas';$('morningLinesSaveIdea').disabled=!editor.value.trim();}
  function renderPrompt(){const page=current(),exercise=exercises[page.exercise];$('morningLinesPrompt').textContent=exercise.prompt;$('morningLinesExerciseName').textContent=exercise.name;$('morningLinesExercise').value=String(page.exercise);}
  function displayTime(){const page=current();$('morningLinesTimer').hidden=page.minutes===0;const seconds=Math.ceil((page.remainingMs??page.minutes*60000)/1000);$('morningLinesTimer').textContent=page.completedAt?'Time':`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;$('morningLinesTimerToggle').textContent=timer?'Pause timer':'Resume timer';$('morningLinesTimerToggle').classList.toggle('hidden',!page.minutes||!page.startedAt||Boolean(page.completedAt));$('morningLines').classList.toggle('time-complete',Boolean(page.completedAt));}
  function pause(){if(!timer)return;current().remainingMs=Math.max(0,deadline-Date.now());clearInterval(timer);timer=null;deadline=null;changed();displayTime();}
  function tick(){current().remainingMs=Math.max(0,deadline-Date.now());if(current().remainingMs===0){clearInterval(timer);timer=null;deadline=null;current().completedAt=now();changed();}displayTime();}
  function runTimer(){const page=current();if(!page.minutes)return;deadline=Date.now()+(page.remainingMs??page.minutes*60000);timer=setInterval(tick,250);tick();}
  function showPage(){const page=current();$('morningLinesPages').classList.add('hidden');$('morningLinesSetup').classList.toggle('hidden',Boolean(page.startedAt));$('morningLinesDesk').classList.toggle('hidden',!page.startedAt);$('morningLinesEditor').value=page.text;renderPrompt();document.querySelectorAll('.morning-lines-times button').forEach(button=>{const active=Number(button.dataset.minutes)===page.minutes;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));});displayTime();wordCount();if(host.renderEditor){const editor=$('morningLinesEditor'),previous=document.getElementById('exerciseOrderedEditor'),container=document.createElement('div');container.id='exerciseOrderedEditor';if(previous)previous.replaceWith(container);else editor.before(container);container.append(host.renderEditor(page,editor,()=>{wordCount();changed();},showPage));}}
  function createPage(){const page={id:`exercise_${crypto.randomUUID()}`,text:'',exercise:0,minutes:5,createdAt:now(),updatedAt:now(),startedAt:null,completedAt:null,remainingMs:300000,copies:[]};host.getState().exercisePages.unshift(page);host.getState().activeExercisePageId=page.id;changed();showPage();}
  async function open(){if(!host)return;returnFocus=document.activeElement;document.body.classList.add('morning-lines-open');$('morningLines').classList.remove('hidden');if(!current()&&host.getState().exercisePages.length)host.getState().activeExercisePageId=host.getState().exercisePages[0].id;if(!current())createPage();else showPage();$('morningLinesClose').focus();}
  async function close(){pause();if(!await flush())return;document.body.classList.remove('morning-lines-open');$('morningLines').classList.add('hidden');host.refresh();returnFocus?.focus();}
  async function newPage(){pause();if(!await flush())return;createPage();$('morningLinesExercise').focus();}
  async function pages(){pause();if(!await flush())return;$('morningLinesSetup').classList.add('hidden');$('morningLinesDesk').classList.add('hidden');const list=$('morningLinesPageList');list.replaceChildren();host.getState().exercisePages.forEach(page=>{const button=document.createElement('button');button.className='exercise-page-card';const title=document.createElement('strong');title.textContent=page.text.split('\n').find(line=>line.trim())||'Blank page';const details=document.createElement('span');details.textContent=`${exercises[page.exercise].name} · ${new Date(page.createdAt).toLocaleDateString()}`;button.append(title,details);button.onclick=()=>action(async()=>{host.getState().activeExercisePageId=page.id;showPage();await flush();(page.startedAt?$('morningLinesEditor'):$('morningLinesExercise')).focus();});list.append(button);});$('morningLinesPages').classList.remove('hidden');list.querySelector('button')?.focus();}
  async function saveToIdeas(){const page=current(),editor=$('morningLinesEditor'),text=editor.selectionEnd>editor.selectionStart?editor.value.slice(editor.selectionStart,editor.selectionEnd):editor.value;if(!text.trim())return;const idea=host.copyIdea(page,text);if(idea)pendingIdeaIds.add(idea.id);changed();if(await flush())status('Saved to Ideas · exercise page kept');}
  async function init(options){
    host=options;recoveryKey=`cowriter-exercise-pending-${host.channel}${host.getState().documentEpoch?`-${host.getState().documentEpoch}`:''}`;
    const state=host.getState();let recovered=false;
    try{const pending=JSON.parse(localStorage.getItem(recoveryKey)||'null'),page=normalisePages(pending?[pending.page]:[])[0];if(page){const index=state.exercisePages.findIndex(item=>item.id===page.id);if(index<0)state.exercisePages.unshift(page);else if(page.updatedAt>=state.exercisePages[index].updatedAt)state.exercisePages[index]=page;for(const idea of pending.ideas||[]){if(idea?.id&&!state.ideas.some(item=>item.id===idea.id)&&!state.songs.some(item=>item.id===idea.id)){state.ideas.unshift(idea);pendingIdeaIds.add(idea.id);}}state.activeExercisePageId=page.id;recovered=true;}}catch(_){}
    // The old key has no release-channel scope. Guided review must not import another build's writing.
    if(!state.exerciseLegacyImported){if(host.channel!=='guided-review'){try{const legacy=JSON.parse(localStorage.getItem(LEGACY_KEY)||'null');if(legacy&&typeof legacy.text==='string'&&legacy.text){const page=normalisePages([{...legacy,id:'exercise_legacy',createdAt:legacy.startedAt||legacy.updatedAt||now(),startedAt:legacy.startedAt||now(),remainingMs:0,completedAt:legacy.completedAt||now()}])[0];if(!state.exercisePages.some(item=>item.id===page.id))state.exercisePages.push(page);state.activeExercisePageId||=page.id;}}catch(_){}}state.exerciseLegacyImported=true;recovered=true;}
    const untimed=document.createElement('button');untimed.type='button';untimed.dataset.minutes='0';untimed.textContent='No timer';document.querySelector('.morning-lines-times').prepend(untimed);
    const expand=document.createElement('button');expand.id='morningLinesExpand';expand.textContent='Expand into Song';expand.className='ghost-button';expand.onclick=()=>action(async()=>{pause();if(!await flush())return;try{await host.expandToSong(current(),exercises[current().exercise].prompt);clearTimeout(saveTimer);try{localStorage.removeItem(recoveryKey);}catch{}document.body.classList.remove('morning-lines-open');$('morningLines').classList.add('hidden');}catch(error){status('Expansion could not save · exercise page kept');}});$('morningLinesSaveIdea').parentElement.append(expand);
    const select=$('morningLinesExercise');exercises.forEach((exercise,index)=>select.add(new Option(exercise.name,String(index))));
    select.onchange=()=>{current().exercise=Number(select.value);renderPrompt();changed();};
    document.querySelectorAll('.morning-lines-times button').forEach(button=>button.onclick=()=>{const page=current();page.minutes=Number(button.dataset.minutes);page.remainingMs=page.minutes*60000;changed();showPage();});
    $('morningLinesBegin').onclick=()=>action(async()=>{current().startedAt=now();changed();showPage();runTimer();$('morningLinesEditor').focus();});
    $('morningLinesClose').onclick=()=>action(close);$('morningLinesNew').onclick=()=>action(newPage);$('morningLinesHistory').onclick=()=>action(pages);
    $('morningLinesSaveIdea').onclick=()=>action(saveToIdeas);$('morningLinesRetry').onclick=()=>action(flush);
    $('morningLinesTimerToggle').onclick=()=>{if(timer)pause();else runTimer();displayTime();};
    $('morningLinesEditor').oninput=()=>{current().text=$('morningLinesEditor').value;wordCount();changed();};
    $('morningLinesEditor').onselect=selectionChanged;
    document.addEventListener('visibilitychange',()=>{if(document.hidden&&current()&&document.body.classList.contains('morning-lines-open')){pause();flush();}});
    window.addEventListener('pagehide',()=>{if(current()&&document.body.classList.contains('morning-lines-open')){pause();journal();}});
    if(recovered)await flush();
  }
  window.CoWriterMorningLines={init,open,normalisePages};
})();
