    const done=document.createElement('button');done.className='primary-button';done.textContent='Keep';done.onclick=async()=>{try{await finaliseRecording(currentTake(take.id)||take);revealSavedWorkTape(take,target);}catch(error){console.warn('Take remains pending',error);}};
