    if(pendingRecording){
      const recording=pendingRecording,audio=document.createElement('audio');audio.controls=true;audio.src=URL.createObjectURL(recording.blob);body.append(audio);
      intro.textContent=message||(recording.interrupted?'This recording was interrupted. The recovered audio may end early; listen before saving.':'This recording is waiting to be saved.');
      const download=document.createElement('button');download.className='ghost-button';download.textContent='Download original audio';download.onclick=()=>downloadBlob(`Recovered-recording.${audioExtension(recording.take)}`,recording.blob);
      const retry=document.createElement('button');retry.className='primary-button';retry.textContent='Save recording';retry.onclick=()=>{retry.disabled=true;savePendingRecording();};
      openModal('Recover recording',body,[download,retry]);studioLogUrls.push(audio.src);return;
    }
