      await finishNotesEditing();clearTimeout(saveTimer);saveTimer=null;
      const demo=inDemoMode();const next=normaliseState(clone(demo?{...state,songs:inSandboxMode()?demoSession.sandboxSongs:[demoSession.song]}:state)),ids=mutate(next);
      els.app.inert=true;els.saveState.textContent='Saving…';
      await activeMediaRepository().commitWorkState(next,{commitId,songIds:ids,...options});
      if(demo){if(inSandboxMode())demoSession.sandboxSongs=next.songs;else demoSession.song=next.songs[0];scheduleSave();return ids;}state=next;
      try{for(const id of ids){const work=state.songs.find(item=>item.id===id);if(work)await songDocuments.replace(work);}await db.request(STORE,'readwrite',store=>store.delete('work-commit-pending'));}
