  function compareWorks(a,b,sort=state.librarySort,direction=state.librarySortDirection){
    const order=sort==='title'?a.title.localeCompare(b.title):new Date(a[sort==='created'?'createdAt':'updatedAt'])-new Date(b[sort==='created'?'createdAt':'updatedAt']);
    return (direction==='asc'?1:-1)*(order||a.id.localeCompare(b.id));
  }
