    const line=item=>{if(item.choices){WM.syncActiveChoice(item);for(const choice of item.choices.items){if(choice.kind==='progression')choice.text=progression(choice.text);choice.chords=choice.chords.map(value=>({...value,value:chord(value.value)}));}}if(item.kind==='progression'||item.type==='harmony')item.text=progression(item.text);item.chords=(item.chords||[]).map(value=>({...value,value:chord(value.value)}));};
